package com.worldfinder.WorldFinder;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.Collections;
import java.util.Set;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup(WorldFinderConfig.GROUP)
public interface WorldFinderConfig extends Config
{
	String GROUP = "worldfinder";

	@ConfigItem(
		keyName = "previousKey",
		name = "Quick-hop previous",
		description = "When you press this key you'll hop to the previous world.",
		position = 0
	)
	default Keybind previousKey()
	{
		return new Keybind(KeyEvent.VK_LEFT, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "nextKey",
		name = "Quick-hop next",
		description = "When you press this key you'll hop to the next world.",
		position = 1
	)
	default Keybind nextKey()
	{
		return new Keybind(KeyEvent.VK_RIGHT, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "quickhopOutOfDanger",
		name = "Quick-hop out of dangerous worlds",
		description = "Don't hop to a PvP/high risk world when quick-hopping.",
		position = 2
	)
	default boolean quickhopOutOfDanger()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSidebar",
		name = "Show world switcher sidebar",
		description = "Show sidebar containing all worlds that mimics in-game interface.",
		position = 4
	)
	default boolean showSidebar()
	{
		return true;
	}

	@ConfigItem(
		keyName = "ping",
		name = "Show world ping",
		description = "Shows ping to each game world.",
		position = 5
	)
	default boolean ping()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMessage",
		name = "Show world hop message in chat",
		description = "Shows what world is being hopped to in the chat.",
		position = 6
	)
	default boolean showWorldHopMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "menuOption",
		name = "Show hop-to menu option",
		description = "Adds Hop-to menu option to the friends list and friends chat members list.",
		position = 7
	)
	default boolean menuOption()
	{
		return true;
	}

	@ConfigItem(
		keyName = "subscriptionFilter",
		name = "Subscription filter",
		description = "Only show free worlds, member worlds, or both types of worlds in sidebar.",
		position = 8
	)
	default SubscriptionFilterMode subscriptionFilter()
	{
		return SubscriptionFilterMode.BOTH;
	}

	@ConfigItem(
		keyName = "regionFilter",
		name = "Region filter",
		description = "Only show and quick-hop to worlds in specific regions.",
		position = 9
	)
	default Set<RegionFilterMode> regionFilter()
	{
		return Collections.emptySet();
	}

	@ConfigItem(
		keyName = "worldTypeFilter",
		name = "World type filter",
		description = "Only show worlds of specific types.",
		position = 10
	)
	default Set<WorldTypeFilter> worldTypeFilter()
	{
		return Collections.emptySet();
	}

	@ConfigItem(
		keyName = "displayPing",
		name = "Display current ping",
		description = "Displays ping to current game world.",
		position = 11
	)
	default boolean displayPing()
	{
		return false;
	}

	@ConfigItem(
		keyName = "skillTotalFilter",
		name = "Skill total filter",
		description = "Only show and quick-hop to these skill total worlds (other worlds are unaffected). Select only None to hide all skill total worlds.",
		position = 12
	)
	default Set<SkillTotalFilter> skillTotalFilter()
	{
		return Collections.emptySet();
	}

	@ConfigItem(
		keyName = "twelveHourTime",
		name = "12 hour time",
		description = "Show the last visited time in 12 hour format.",
		position = 13
	)
	default boolean twelveHourTime()
	{
		return false;
	}
}

package com.worldfinder.WorldFinder;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.http.api.worlds.World;

@Singleton
class WorldFinderExtension
{
	private static final int HOP_START_TIMEOUT_TICKS = 5;
	private static final DateTimeFormatter TIME_24H = DateTimeFormatter.ofPattern("HH:mm");
	private static final DateTimeFormatter TIME_12H = DateTimeFormatter.ofPattern("hh:mm");

	@Inject
	private Client client;

	@Inject
	private WorldFinderConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	private final Map<Integer, Long> lastVisited = new ConcurrentHashMap<>();
	private Runnable onTimersChanged;
	// client thread only
	private int hopSentTick = -1;
	private boolean hopStarted;

	void startUp(Runnable onTimersChanged)
	{
		this.onTimersChanged = onTimersChanged;
		migrateConfig();
		wsClient.registerMessage(WorldTimerUpdate.class);
		eventBus.register(this);
	}

	void shutDown()
	{
		eventBus.unregister(this);
		wsClient.unregisterMessage(WorldTimerUpdate.class);
		clearHop();
	}

	private void migrateConfig()
	{
		// ConfigManager deserializes unknown enum names to null, which breaks WorldTypeFilter matching
		String worldTypes = configManager.getConfiguration(WorldFinderConfig.GROUP, "worldTypeFilter");
		if (worldTypes != null && worldTypes.contains("\"TARGET\""))
		{
			configManager.setConfiguration(WorldFinderConfig.GROUP, "worldTypeFilter",
				worldTypes.replace("\"TARGET\"", "\"BOUNTY_HUNTER\""));
		}
	}

	void onWorldChanged(int fromWorld, int toWorld)
	{
		stamp(fromWorld);
		stamp(toWorld);
		onTimersChanged.run();
	}

	private void stamp(int worldId)
	{
		if (worldId <= 0)
		{
			return;
		}

		long now = System.currentTimeMillis();
		lastVisited.put(worldId, now);
		if (partyService.isInParty())
		{
			partyService.send(new WorldTimerUpdate(worldId, now));
		}
	}

	@Subscribe
	public void onWorldTimerUpdate(WorldTimerUpdate update)
	{
		lastVisited.put(update.getWorldId(), update.getTimeStamp());
		onTimersChanged.run();
	}

	@Nullable
	Long getLastVisited(int worldId)
	{
		return lastVisited.get(worldId);
	}

	String formatLastVisited(@Nullable Long timestamp)
	{
		if (timestamp == null)
		{
			return "-";
		}

		DateTimeFormatter format = config.twelveHourTime() ? TIME_12H : TIME_24H;
		return format.format(Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault()));
	}

	boolean isFiltered(World world)
	{
		Set<SkillTotalFilter> skillTotals = config.skillTotalFilter();
		String activity = world.getActivity();
		if (!skillTotals.isEmpty() && activity != null && activity.contains("skill total"))
		{
			return skillTotals.stream().noneMatch(f -> activity.equals(f.getSkillTotal()));
		}

		return false;
	}

	// A hop requested before the current one completes would be queued and fire after landing
	boolean isHopInProgress()
	{
		return hopSentTick >= 0;
	}

	void onHopSent()
	{
		hopSentTick = client.getTickCount();
		hopStarted = false;
	}

	private void clearHop()
	{
		hopSentTick = -1;
		hopStarted = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!isHopInProgress())
		{
			return;
		}

		switch (event.getGameState())
		{
			case HOPPING:
				hopStarted = true;
				break;
			case LOGGED_IN:
				if (hopStarted)
				{
					clearHop();
				}
				break;
			case LOGIN_SCREEN:
				clearHop();
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The hop never started, e.g. the server refused it during combat
		if (isHopInProgress() && !hopStarted && client.getTickCount() - hopSentTick > HOP_START_TIMEOUT_TICKS)
		{
			clearHop();
		}
	}
}

