				// If the player has disabled the side bar plugin panel, do not update the UI
				if (config.showSidebar())
				{
					panel.switchCurrentHighlight(newWorld, lastWorld);
				}
				currentPing = -1;
				worldFinder.onWorldChanged(lastWorld, newWorld);
				lastWorld = newWorld;
			}
		}
	}

